const { env } = await import('node:process');
const doc = env.STROC_DOC;
if (!doc) { throw new Error('Missing STROC_DOC'); }
globalThis.strocDoc = doc;

const mod = await import('@stroc/pdf');
const { toPdf } = mod;
const doc = JSON.parse(globalThis.strocDoc);
const pdfBytes = await toPdf(doc, { pageSize: 'A4' });
globalThis.pdfBase64 = Buffer.from(pdfBytes).toString('base64');
